    internal static int Run(string input,string output,bool singleOwner=false)
    {
        string cwd=Directory.GetCurrentDirectory();NativeWindow? window=null;DesktopGraphicsSession? graphics=null;
        try
        {
            input=Path.GetFullPath(input);output=Path.GetFullPath(output);Directory.CreateDirectory(output);string loaded=typeof(Scene).Assembly.Location;Console.WriteLine("Loaded ProjectPrime: "+loaded+" SHA256="+Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(loaded))));string data=File.ReadAllText(Path.Combine(input,"replay-fixture-data.txt"));Directory.SetCurrentDirectory(data);Paths.UpdatePaths();Paths.ChooseMphPath();MapAudit.ForceEveryone=true;
            string archive=Path.Combine(input,"actual-full-custom"+DemoFile.Extension);using var json=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(input,"file-expected-worlds.json")));var rows=json.RootElement.EnumerateArray().Select(row=>(Name:row.GetProperty("name").GetString()!,Frame:row.GetProperty("frame").GetUInt32(),Filename:row.GetProperty("filename").GetString()!)).ToArray();if(rows.Length is <1 or >8)throw new InvalidDataException("Bounded actual targets required.");var end=rows.Single(row=>row.Name=="end");var store=new WeaponPackageStore(Path.Combine(output,"store"));byte[] package=File.ReadAllBytes(Path.Combine(input,"variant.ppweapon"));if(package.Length>32*1024*1024)throw new InvalidDataException("Package bound.");var parsedPackage=WeaponPackage.Parse(package);store.Install(package);
            var settings=DesktopGlContext.Settings(background:true);settings.ClientSize=new(640,480);settings.StartVisible=true;settings.Title="Private custom replay first person";window=new NativeWindow(settings);graphics=new DesktopGraphicsSession(window);
            int checks=0,selected=0,customModels=0,scoped=0,nativePovSamples=0,reloadingSamples=0,optic4Samples=0;var selectedSlots=new HashSet<int>();void Check(bool ok,string label){if(!ok)throw new InvalidDataException(label);checks++;}const BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;object? Field(Scene scene,string name)=>typeof(Scene).GetField(name,hidden)!.GetValue(scene);Vector3 Camera(Scene scene)=>(Vector3)Field(scene,"_cameraPosition")!;float Fov(Scene scene)=>(float)Field(scene,"_cameraFov")!;var evidence=new List<object>();
            var live=new Scene(window.FramebufferSize,SyntheticInput.CreateKeyboard(),SyntheticInput.CreateMouse(),_=>{},()=>{});Check(!live.SetCustomInspectionFirstPerson(0)&&live.CustomInspectionFirstPersonSlot==-1,"ordinary live Scene refuses private archive POV");live.ClearCustomInspectionFirstPerson();live.DoCleanup();
            foreach(var row in rows.Reverse())
