                var foreground=GameState.Current;var random=Rng.Current;uint rng1=Rng.Rng1,rng2=Rng.Rng2;bool active=DemoPlayback.IsActive;object request=DemoPlayback.RequestOwner;bool spectator=SpectatorMode.IsSpectating,prefer=SpectatorMode.PreferSpectator,free=SpectatorMode.FreeCamera;bool network=NetSession.Active;
                using var prepared=Task.Run(()=>PreparedCustomReplayArchive.Prepare(archive,store,row.Frame)).GetAwaiter().GetResult();if(row.Name=="end"){using var detachedWorld=prepared.CopyWorld();using var detached=PassiveReplayScene.RestoreCustomInspection(detachedWorld,prepared.Resources,new Vector2i(640,480));Check(!detached.Scene.SetCustomInspectionFirstPerson(0)&&detached.Scene.CustomInspectionFirstPersonSlot==-1,"detached custom world without admitted file cursor refuses private POV");}using var scene=PassiveReplayScene.OpenCustomArchiveInspection(prepared,new Vector2i(640,480));prepared.Dispose();int main=scene.Scene.Players.MainPlayerIndex;using var expected=ReplayWorldCheckpoint.FromCustomBytes(File.ReadAllBytes(Path.Combine(input,row.Filename)));using(var before=ReplayWorldCheckpoint.CaptureCustom(scene))Check(expected.CanonicalGraphDifferences(before).Length==0,"fresh reverse target canonical parity "+row.Name);
                Check(!scene.Scene.SetCustomInspectionFirstPerson(-1)&&!scene.Scene.SetCustomInspectionFirstPerson(8)&&scene.Scene.CustomInspectionFirstPersonSlot==-1,"invalid slots refuse empty selection "+row.Name);
                for(int slot=0;slot<(singleOwner?1:2);slot++)
                {
                    bool accepted=scene.Scene.SetCustomInspectionFirstPerson(slot);if(!accepted){Check(scene.Scene.CustomInspectionFirstPersonSlot is >=-1 and <8,"unavailable native actor refused without global fallback "+row.Name+"/"+slot);continue;}selected++;selectedSlots.Add(slot);Check(scene.Scene.CustomInspectionFirstPersonSlot==slot,"POV selects exact private actor "+row.Name+"/"+slot);Check(!scene.Scene.SetCustomInspectionFirstPerson(99)&&scene.Scene.CustomInspectionFirstPersonSlot==slot,"invalid switch preserves previous valid POV");
                    for(int draw=0;draw<3;draw++)
                    {
                        using var before=ReplayWorldCheckpoint.CaptureCustom(scene);float nativeCameraFovBefore=scene.Scene.Players.Items[slot].CameraInfo.Fov;scene.Scene.OnDrawFrame();Check(scene.Scene.OnRenderFrame()&&GL.GetError()==OpenTK.Graphics.OpenGL.ErrorCode.NoError,"actual private POV native GL renders");Check(scene.Scene.Players.MainPlayerIndex==main,"render-only MainPlayerIndex loan returns before caller resumes");Vector3 eye=Camera(scene.Scene);float fov=Fov(scene.Scene);Check(float.IsFinite(eye.X)&&float.IsFinite(eye.Y)&&float.IsFinite(eye.Z)&&float.IsFinite(fov)&&fov>0&&fov<MathF.PI,"actual private eye and world FOV are finite");
                        var actor=scene.Scene.Players.Items[slot];Check(actor.ModReplayPresentationCamera(scene.Scene.ReplayRenderAlpha,out var expectedView,out var expectedEye,out float authoredFov),"chosen actor supplies recorded replica first-person camera");float authored=authoredFov>0?authoredFov:RenderOptions.DefaultFov;float expectedFov=MathHelper.DegreesToRadians(RenderOptions.ScaleCameraFov(authored));float expectedGun=MathHelper.DegreesToRadians(Math.Clamp(authored,1f,175f));var actualView=(Matrix4)Field(scene.Scene,"_viewMatrix")!;Check((eye-expectedEye).Length<.0001f&&MathF.Abs(fov-expectedFov)<.00001f&&MathF.Abs((float)Field(scene.Scene,"_viewModelFov")!-expectedGun)<.00001f,"chosen actor eye and scaled world/authored viewmodel FOV match actual camera");Check((actualView.Row0-expectedView.Row0).Length<.0001f&&(actualView.Row1-expectedView.Row1).Length<.0001f&&(actualView.Row2-expectedView.Row2).Length<.0001f&&(actualView.Row3-expectedView.Row3).Length<.0001f,"actual view matrix follows chosen actor rather than default slot");Check(scene.Scene.ReplayOwnerProvenance.Contains("authority reconstructed",StringComparison.OrdinalIgnoreCase)&&!scene.Scene.ReplayOwnerProvenance.Contains("Owner captured",StringComparison.OrdinalIgnoreCase),"sidecar-free fixture truthfully reports reconstructed POV provenance");var hud=scene.Scene.CustomWeaponHud(actor);bool custom=hud.Ready&&hud.Visible;int magnificationMilli=1000;float? independentScopeFov=null;Check(actor.CameraInfo.Fov==nativeCameraFovBefore,"POV projection never rewrites canonical native CameraInfo FOV");if(custom){Check(scene.Scene.CustomRifleModel!=null&&actor.ModTryCustomRifleTransform(true,0,out var transform,out var muzzle)&&float.IsFinite(muzzle.X)&&float.IsFinite(transform.M11),"prepared custom first-person barrel/model transform available");customModels++;if(hud.State.Phase==CustomWeaponPhase.Reloading)reloadingSamples++;if(hud.State.Optic==4)optic4Samples++;Check(hud.Optic==hud.State.Optic,"custom optic derives exact recorded runtime state");if(hud.State.Optic>0){int optic=hud.State.Optic;var optics=parsedPackage.Definition.Mechanics.OpticMagnificationsMilli;Check(optic<=optics.Count,"recorded optic indexes exact immutable package optics");magnificationMilli=optics[optic-1];float normal=Fixed.ToFloat(actor.Values.NormalFov)*2;float ratio=magnificationMilli/1000f;float lens=2*MathF.Atan(MathF.Tan(normal*MathF.PI/360)/ratio)*180/MathF.PI;independentScopeFov=lens;Check(MathF.Abs(authoredFov-lens)<.0001f,"accepted custom optic independently derives settled exact package lens FOV");float actualRatio=MathF.Tan(normal*MathF.PI/360)/MathF.Tan(authoredFov*MathF.PI/360);Check(MathF.Abs(actualRatio-ratio)<.0001f,"projection-space tangent ratio equals exact accepted magnification");Check(MathF.Abs(actor.CameraInfo.Fov-normal)<.0001f&&actor.CameraInfo.Fov==nativeCameraFovBefore,"scoped private projection preserves native unscoped canonical CameraInfo");scoped++;}}
                        if(!custom)nativePovSamples++;
                        if(draw==0)Check(ScreenCapture.SaveWindow(scene.Scene,Path.Combine(output,row.Name+"-slot"+slot+"-window.png"))&&ScreenCapture.Save(scene.Scene,Path.Combine(output,row.Name+"-slot"+slot+"-world.png")),"actual source/target private POV images retained");DesktopGraphicsSession.Present(window);scene.Scene.AfterRenderFrame();using var after=ReplayWorldCheckpoint.CaptureCustom(scene);var differences=before.CanonicalGraphDifferences(after);File.WriteAllText(Path.Combine(output,row.Name+"-slot"+slot+"-draw"+draw+"-differences.json"),JsonSerializer.Serialize(differences));Check(differences.Length==0,"strict whole canonical graph unchanged by POV draw");Check(!ReplayAudioOwner.MayPlay(scene.Scene)&&Field(scene.Scene,"_customRifleAudio")==null,"private POV retains silent presentation/audio ownership");evidence.Add(new{row.Name,row.Frame,slot,draw,eye=new[]{eye.X,eye.Y,eye.Z},fov,custom,optic=hud.State.Optic,authoredFov,expectedFov,expectedGun,magnificationMilli,independentScopeFov,nativeCameraFov=actor.CameraInfo.Fov,provenance=scene.Scene.ReplayOwnerProvenance,mainAfter=scene.Scene.Players.MainPlayerIndex});
                    }
                }
                scene.Scene.ClearCustomInspectionFirstPerson();Check(scene.Scene.CustomInspectionFirstPersonSlot==-1&&scene.Scene.Players.MainPlayerIndex==main,"clear restores private roam without canonical main mutation");
                while(!scene.Session.AtEnd){if(!scene.StepCustomArchiveInspection())break;foreach(var target in rows.Where(target=>target.Frame==scene.Session.RecordingFrame)){using var targetExpected=ReplayWorldCheckpoint.FromCustomBytes(File.ReadAllBytes(Path.Combine(input,target.Filename)));using var actual=ReplayWorldCheckpoint.CaptureCustom(scene);Check(targetExpected.CanonicalGraphDifferences(actual).Length==0,"strict genuine suffix after private POV draws "+row.Name+"→"+target.Name);}}
                using(var expectedEnd=ReplayWorldCheckpoint.FromCustomBytes(File.ReadAllBytes(Path.Combine(input,end.Filename))))using(var actualEnd=ReplayWorldCheckpoint.CaptureCustom(scene))Check(expectedEnd.CanonicalGraphDifferences(actualEnd).Length==0,"POV inspected owner reaches genuine final whole world");Check(ReferenceEquals(foreground,GameState.Current)&&ReferenceEquals(random,Rng.Current)&&rng1==Rng.Rng1&&rng2==Rng.Rng2&&active==DemoPlayback.IsActive&&ReferenceEquals(request,DemoPlayback.RequestOwner)&&spectator==SpectatorMode.IsSpectating&&prefer==SpectatorMode.PreferSpectator&&free==SpectatorMode.FreeCamera&&network==NetSession.Active,"private POV leaves global replay spectator input/network and RNG owners unchanged");
            }
            var beforeContact=rows.FirstOrDefault(row=>row.Name=="before-body");if(!singleOwner&&beforeContact.Name!=null)
            {
                using var lifetimePrepared=Task.Run(()=>PreparedCustomReplayArchive.Prepare(archive,store,beforeContact.Frame)).GetAwaiter().GetResult();using var lifetime=PassiveReplayScene.OpenCustomArchiveInspection(lifetimePrepared,new Vector2i(640,480));Check(lifetime.Scene.SetCustomInspectionFirstPerson(1),"genuine precontact target selects private life-bound POV");lifetime.State.TryGetPlayer(1,out var initialLife);bool retired=false;
                while(!lifetime.Session.AtEnd){if(!lifetime.StepCustomArchiveInspection())break;if(!lifetime.State.TryGetPlayer(1,out var current)||current.Health==0||current.SlotGeneration!=initialLife.SlotGeneration||current.LifeId!=initialLife.LifeId){using var before=ReplayWorldCheckpoint.CaptureCustom(lifetime);lifetime.Scene.OnDrawFrame();Check(lifetime.Scene.OnRenderFrame(),"lifecycle revalidation picture renders");lifetime.Scene.AfterRenderFrame();using var after=ReplayWorldCheckpoint.CaptureCustom(lifetime);Check(lifetime.Scene.CustomInspectionFirstPersonSlot==-1&&before.CanonicalGraphDifferences(after).Length==0,"death/newlife clears private POV without canonical mutation");retired=true;break;}}
